const AWS = require('aws-sdk');
const ddb = new AWS.DynamoDB.DocumentClient();
exports.handler = async (event) => {
  for (const rec of event.Records) {
    const body = JSON.parse(rec.body); // or rec.kinesis, etc.
    const id = `${rec.s3.object.key}:${body.recordId}`;
    // Idempotency: check or upsert
    const exists = await ddb.get({TableName:'SeenIds', Key:{id}}).promise();
    if (exists.Item) continue;
    await ddb.put({TableName:'SeenIds', Item:{id}}).promise();
    // transform and write to target bucket
